begin;
create temp table _imp(tipo text, ref text, lote text, pos text, ocorrido timestamp, estado int, toolid text, movid int, opid uuid) on commit drop;
update _imp i set toolid = t."ToolId" from "Tools" t where t."Type" = i.tipo and upper(t."Reference") = upper(i.ref) and t."Lot" = i.lote;
-- ferramentas que faltam (id T + 10 hex)
update _imp set toolid = 'T' || substr(md5(random()::text || tipo || ref || lote), 1, 10) where toolid is null;
 select i.toolid, i.tipo, i.ref, i.lote, now() from _imp i
 where not exists (select 1 from "Tools" t where t."ToolId" = i.toolid);
-- uma só linha por ferramenta: a mais recente
delete from _imp a using _imp b where a.toolid = b.toolid and (a.ocorrido, a.opid) < (b.ocorrido, b.opid);
-- só quem ainda não está numa posição
delete from _imp i using "ArmazemOcupacoes" o where o."ToolId" = i.toolid and o."LibertadaEmUtc" is null;
with m as (
 select 1, i.toolid, p."Id", 5, i.estado, 'Importado do SharePoint', i.ocorrido, now(), 'importacao', i.opid, 'import'
 from _imp i join "ArmazemPosicoes" p on p."Codigo" = i.pos returning "Id","ToolId","PosicaoId","OcorridoEmUtc")
 select i.toolid, i.estado, 'armazem', mv."Id", now(), 'importacao' from _imp i join "ArmazemMovimentos" mv on mv."OperacaoId" = i.opid where i.estado is not null;
commit;
